import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-attendance.json"), "utf8"),
);
const models = emitModels(contract.models, "attendanceStatusSchema");
const list = (values) =>
  Object.keys(values)
    .map((k) => JSON.stringify(k))
    .join(",");
let go =
  '// Code generated by scripts/generate-workforce-attendance.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
go += `var attendanceStatuses=[]string{${list(contract.statuses)}}\n`;
go += `var attendanceExceptions=[]string{${list(contract.exceptions)}}\n`;
let ts = '// Generated by scripts/generate-workforce-attendance.mjs.\nimport { z } from "zod";\n\n';
ts += `export const ATTENDANCE_STATUSES=${JSON.stringify(contract.statuses)} as const;\nexport const attendanceStatusSchema=z.enum(${JSON.stringify(Object.keys(contract.statuses))});\n`;
ts += `export const ATTENDANCE_EXCEPTIONS=${JSON.stringify(contract.exceptions)} as const;\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/attendance_types.go",
  go + models.go,
  "packages/api/src/attendance-contract.ts",
  ts + models.ts,
  "attendance",
);
